// Lloyd-Max for N(0, 1/128); identical to CENTROIDS_* / nearest_centroid_* in ggml-turbo-quant.c.
static const float kCent3[8] = { -0.190207f, -0.118786f, -0.066822f, -0.021663f, 0.021663f, 0.066822f, 0.118786f, 0.190207f };
